settings.custom_css:
/* ===== Venus club popup - generated by _build/make-club-popup.mjs ===== */
selector{--padding-top:0px;--padding-right:0px;--padding-bottom:0px;--padding-left:0px;--gap:0px;gap:0;background:#FFFBE9;font-family:var(--e-global-typography-vnsbody-font-family),"Discovery Fs",system-ui,sans-serif;color:#141414;direction:rtl;min-height:0}
selector *{box-sizing:border-box}
selector .vcl-form{--padding-top:44px;--padding-right:44px;--padding-bottom:36px;--padding-left:44px;--gap:0px;gap:0;justify-content:center;width:54%;flex:none}
selector .vcl-img{width:46%;flex:none;min-height:100%;background-size:cover!important;background-position:50% 35%!important}
selector .vcl-h .elementor-heading-title{margin:0;font-family:var(--e-global-typography-vnsheading-font-family),"Leon","Discovery Fs",system-ui,sans-serif!important;font-weight:700;font-size:34px;line-height:1.12;color:#141414}
selector .vcl-h .elementor-heading-title b{font-weight:inherit;color:var(--e-global-color-vnsgreen,#3A4831)}
selector .vcl-sub .elementor-heading-title{margin:10px 0 22px;font-family:var(--e-global-typography-vnsbody-font-family),"Discovery Fs",system-ui,sans-serif!important;font-weight:300;font-size:18px;line-height:1.5;color:#3d3d3a}
selector .elementor-widget{margin:0}
selector .elementor-form .elementor-field-group{margin-bottom:14px}
selector .elementor-form .elementor-field-label{display:block;margin:0 0 6px;padding:0;font-family:var(--e-global-typography-vnsbody-font-family),"Discovery Fs",system-ui,sans-serif!important;font-size:15px!important;font-weight:500!important;line-height:1.3;color:#141414!important}
selector .elementor-form .elementor-mark-required .elementor-field-label:after{color:#8A2B1D}
selector .elementor-form .elementor-field-textual{min-height:48px;padding:10px 14px!important;border:1px solid #8C8A80!important;border-radius:6px!important;background:#fff!important;color:#141414!important;font-family:var(--e-global-typography-vnsbody-font-family),"Discovery Fs",system-ui,sans-serif!important;font-size:17px!important;font-weight:300!important;line-height:1.3;box-shadow:none!important}
selector .elementor-form .elementor-field-textual::placeholder{color:#6B6A63;opacity:1}
selector .elementor-form .elementor-field-textual:focus{border-color:var(--e-global-color-vnsgreen,#3A4831)!important;outline:2px solid var(--e-global-color-vnsgreen,#3A4831);outline-offset:1px}
selector .elementor-form input[type=date].elementor-field-textual{direction:rtl;text-align:right}
selector .elementor-form .elementor-field-type-submit{margin:6px 0 0}
selector .elementor-form .elementor-button{width:100%;min-height:52px;padding:0 24px;border:0;border-radius:12px!important;background:var(--e-global-color-vnsgreen,#3A4831)!important;color:#fff!important;font-family:var(--e-global-typography-vnsbody-font-family),"Discovery Fs",system-ui,sans-serif!important;font-size:18px!important;font-weight:500!important;line-height:1;transition:background .15s}
selector .elementor-form .elementor-button:hover{background:#2C3624!important}
selector .elementor-form .elementor-button:focus-visible{outline:3px solid #141414;outline-offset:2px}
selector .elementor-form .elementor-message{margin-top:12px;font-size:16px;line-height:1.4}
selector .elementor-form .elementor-message-success{color:var(--e-global-color-vnsgreen,#3A4831)}
selector .elementor-form .elementor-message-danger,selector .elementor-form .elementor-error .elementor-field-textual{color:#8A2B1D;border-color:#8A2B1D!important}
selector .vcl-note .elementor-heading-title{margin:12px 0 0;font-family:var(--e-global-typography-vnsbody-font-family),"Discovery Fs",system-ui,sans-serif!important;font-size:14px;font-weight:300;line-height:1.45;color:#4a4a46;text-align:center}
selector .vcl-note a{color:var(--e-global-color-vnsgreen,#3A4831);text-decoration:underline;text-underline-offset:2px}
@media(max-width:1024px){
selector .vcl-form{--padding-top:36px;--padding-right:32px;--padding-bottom:30px;--padding-left:32px;width:60%}
selector .vcl-img{width:40%}
selector .vcl-h .elementor-heading-title{font-size:30px}
}
@media(max-width:767px){
selector .vcl-form{--padding-top:44px;--padding-right:20px;--padding-bottom:24px;--padding-left:20px;width:100%}
selector .vcl-img{display:none}
selector .vcl-h .elementor-heading-title{font-size:28px}
selector .vcl-sub .elementor-heading-title{font-size:17px;margin-bottom:18px}
}
